/**
 * Compatibility structure API. Runtime ship geometry is generated by each
 * vessel's own architecture/hull-geometry.js and component generators.
 */
import { VESSEL_SPECS } from '../vessels/index.js?v=0.8.11';
import {
  SHIP_STRUCTURE_MODULE_VERSION, getShipStructureFromSpec,
  setStructureOverrideForSpec, resetStructureOverrideForSpec
} from './vessel-definition.js?v=0.8.11';
import {
  getCrossSectionHalfBreadthRatio, getKeelLineHeight, getLongitudinalHalfBeamRatio
} from './ship-hull-parameterization.js?v=0.8.11';

const normaliseId = (type) => String(type ?? '').replace(/^ship-/, '');
const vesselSpec = (type) => VESSEL_SPECS[normaliseId(type)] ?? null;
const profiles = Object.fromEntries(Object.entries(VESSEL_SPECS).map(([id, vessel]) => [id, vessel.definition.structure]));
for (const profile of Object.values(profiles)) Object.freeze(profile);
export const SHIP_STRUCTURE_CATALOGUE_VERSION = SHIP_STRUCTURE_MODULE_VERSION;
export { SHIP_STRUCTURE_MODULE_VERSION };
export const SHIP_STRUCTURE_BLUEPRINTS = Object.freeze(profiles);
const clamp01 = (value) => Math.max(0, Math.min(1, Number(value) || 0));

export function setShipStructureOverrides(type, overrides = {}) {
  const vessel = vesselSpec(type);
  return vessel ? setStructureOverrideForSpec(vessel.definition, overrides) : false;
}
export function resetShipStructureOverrides(type) {
  const vessel = vesselSpec(type);
  return vessel ? resetStructureOverrideForSpec(vessel.definition) : false;
}
export function getShipStructureBlueprint(type) {
  const vessel = vesselSpec(type);
  return vessel ? getShipStructureFromSpec(vessel.definition) : null;
}
export function getHullHalfBeam(design, station) {
  const profile = getShipStructureBlueprint(design?.id);
  if (!profile) return (design?.beamUnits ?? 0) * .5;
  return design.beamUnits * .5 * getLongitudinalHalfBeamRatio(design, profile, station);
}
export function getHullSectionWidth(design, vertical) {
  const profile = getShipStructureBlueprint(design?.id);
  return profile ? getCrossSectionHalfBreadthRatio(design, profile, vertical) : 1;
}
export function getHullKeelY(design, station) {
  const profile = getShipStructureBlueprint(design?.id);
  return profile ? getKeelLineHeight(design, profile, station) : -(design?.draftUnits ?? 0);
}
export function getDeckSheer(design, station) {
  const t = clamp01(station);
  const edge = Math.pow(Math.abs(t - .5) * 2, 1.28);
  const bowRise = t < .5 ? design.hull.bowRise : design.hull.sternRise;
  const profile = getShipStructureBlueprint(design.id);
  return design.deckHeightUnits
    + design.hull.sheer * design.deckHeightUnits * edge
    + bowRise * design.deckHeightUnits * Math.pow(edge, 1.18) * (profile?.sheer ?? 1);
}
export function getHullFrameCount(design) {
  return getShipStructureBlueprint(design?.id)?.frameCount ?? 18;
}
